--
-- Name: audit_logs_block_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_logs_block_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only: % is not allowed', TG_OP;
END;
$$;


--
-- Name: bill_items_only_while_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bill_items_only_while_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  bill_state bill_status;
BEGIN
  SELECT status INTO bill_state FROM bills WHERE id = coalesce(NEW.bill_id, OLD.bill_id) FOR SHARE;
  IF bill_state IS DISTINCT FROM 'open' THEN
    RAISE EXCEPTION 'Lines of a % bill can''t change', bill_state;
  END IF;
  RETURN coalesce(NEW, OLD);
END;
$$;


--
-- Name: bill_payments_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bill_payments_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
    OR NEW.bill_id IS DISTINCT FROM OLD.bill_id
    OR NEW.mode IS DISTINCT FROM OLD.mode
    OR NEW.share_index IS DISTINCT FROM OLD.share_index
    OR NEW.method IS DISTINCT FROM OLD.method THEN
    RAISE EXCEPTION 'A bill payment''s amount and what it covers can''t change';
  END IF;
  IF OLD.status <> 'pending' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'A % bill payment is final', OLD.status;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bills_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bills_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  lines_total integer;
BEGIN
  IF NEW.restaurant_id IS DISTINCT FROM OLD.restaurant_id
    OR NEW.table_session_id IS DISTINCT FROM OLD.table_session_id
    OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'A bill''s restaurant, visit and currency can''t change';
  END IF;
  IF OLD.status <> 'open' THEN
    IF NEW.status = 'open' THEN
      RAISE EXCEPTION 'A finalized bill can''t be reopened';
    END IF;
    IF OLD.status IN ('paid', 'void') AND NEW.status IS DISTINCT FROM OLD.status THEN
      RAISE EXCEPTION 'A % bill is final', OLD.status;
    END IF;
    IF NEW.subtotal_minor IS DISTINCT FROM OLD.subtotal_minor
      OR NEW.discount_minor IS DISTINCT FROM OLD.discount_minor
      OR NEW.service_fee_bps IS DISTINCT FROM OLD.service_fee_bps
      OR NEW.service_fee_minor IS DISTINCT FROM OLD.service_fee_minor
      OR NEW.tax_included_minor IS DISTINCT FROM OLD.tax_included_minor
      OR NEW.vat_rate_bps IS DISTINCT FROM OLD.vat_rate_bps
      OR NEW.total_minor IS DISTINCT FROM OLD.total_minor THEN
      RAISE EXCEPTION 'A finalized bill''s amounts can''t change';
    END IF;
  ELSIF NEW.status = 'paid' THEN
    RAISE EXCEPTION 'A bill must be finalized before it is paid';
  ELSIF NEW.status = 'finalized' THEN
    SELECT coalesce(sum(line_total_minor), 0) INTO lines_total FROM bill_items WHERE bill_id = NEW.id;
    IF lines_total <> NEW.subtotal_minor THEN
      RAISE EXCEPTION 'Bill lines add up to %, not the subtotal %', lines_total, NEW.subtotal_minor;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: block_financial_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_financial_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION '% on % is not allowed: financial records are immutable', TG_OP, TG_TABLE_NAME;
END;
$$;


--
-- Name: orders_lock_amounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orders_lock_amounts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.subtotal_minor <> OLD.subtotal_minor OR NEW.discount_minor <> OLD.discount_minor
     OR NEW.total_minor <> OLD.total_minor OR NEW.currency <> OLD.currency
     OR NEW.restaurant_id <> OLD.restaurant_id OR NEW.number <> OLD.number
     OR NEW.table_session_id <> OLD.table_session_id THEN
    RAISE EXCEPTION 'An order''s amounts, currency, number and session can''t change after it is placed';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payment_refunds_lock_terms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_refunds_lock_terms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
    OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
    OR NEW.restaurant_id IS DISTINCT FROM OLD.restaurant_id
    OR (OLD.status <> 'pending' AND NEW.status IS DISTINCT FROM OLD.status)
  THEN
    RAISE EXCEPTION 'A refund''s amount and payment can''t change, nor a finished refund''s status';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: payments_lock_terms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_lock_terms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
    OR NEW.currency IS DISTINCT FROM OLD.currency
    OR NEW.provider IS DISTINCT FROM OLD.provider
    OR NEW.restaurant_id IS DISTINCT FROM OLD.restaurant_id
    OR NEW.purpose IS DISTINCT FROM OLD.purpose
    OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
    OR (OLD.provider_payment_id IS NOT NULL AND NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id)
  THEN
    RAISE EXCEPTION 'A payment''s amount, currency, provider and target can''t change after it is created';
  END IF;
  RETURN NEW;
END;
$$;


