--
-- Name: bill_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bill_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    restaurant_id uuid NOT NULL,
    bill_id uuid NOT NULL,
    order_item_id uuid,
    member_id uuid,
    name text NOT NULL,
    options jsonb DEFAULT '[]'::jsonb NOT NULL,
    unit_price_minor integer NOT NULL,
    modifiers_total_minor integer DEFAULT 0 NOT NULL,
    quantity smallint NOT NULL,
    line_total_minor integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bill_items_line_total CHECK ((line_total_minor = ((unit_price_minor + modifiers_total_minor) * quantity))),
    CONSTRAINT bill_items_prices CHECK (((unit_price_minor >= 0) AND (modifiers_total_minor >= 0))),
    CONSTRAINT bill_items_quantity CHECK (((quantity >= 1) AND (quantity <= 50)))
);


