    CONSTRAINT reviews_comment_length CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
    CONSTRAINT reviews_display_name CHECK (((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 60))),
    CONSTRAINT reviews_email_lowercase CHECK (((author_email IS NULL) OR (author_email = lower(author_email)))),
    CONSTRAINT reviews_guest_email CHECK (((author_guest_id IS NULL) OR (author_email IS NOT NULL))),
    CONSTRAINT reviews_rating CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT reviews_report_reason CHECK (((reported_at IS NULL) OR ((length(TRIM(BOTH FROM report_reason)) >= 10) AND (length(TRIM(BOTH FROM report_reason)) <= 500)))),
    CONSTRAINT reviews_response_length CHECK (((response IS NULL) OR (length(response) <= 2000))),
    CONSTRAINT reviews_subject_target CHECK ((((subject = 'reservation'::public.review_subject) AND (reservation_id IS NOT NULL) AND (table_session_id IS NULL)) OR ((subject = 'visit'::public.review_subject) AND (table_session_id IS NOT NULL) AND (reservation_id IS NULL))))
